   185	    /// Adds two values. Errors if invalid.
   186	    pub fn checked_add(&self, other: &Self) -> Result<Self> {
   187	        use Value::*;
   188	
   189	        Ok(match (self, other) {
   190	            (Integer(lhs), Integer(rhs)) => match lhs.checked_add(*rhs) {
   191	                Some(i) => Integer(i),
   192	                None => return errinput!("integer overflow"),
   193	            },
   194	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 + rhs),
   195	            (Float(lhs), Integer(rhs)) => Float(lhs + *rhs as f64),
   196	            (Float(lhs), Float(rhs)) => Float(lhs + rhs),
   197	            (Null, Integer(_) | Float(_) | Null) => Null,
   198	            (Integer(_) | Float(_), Null) => Null,
   199	            (lhs, rhs) => return errinput!("can't add {lhs} and {rhs}"),
   200	        })
   201	    }
   202	
   203	    /// Divides two values. Errors if invalid.
   204	    pub fn checked_div(&self, other: &Self) -> Result<Self> {
   205	        use Value::*;
   206	
   207	        Ok(match (self, other) {
   208	            (Integer(_), Integer(0)) => return errinput!("can't divide by zero"),
   209	            (Integer(lhs), Integer(rhs)) => Integer(lhs / rhs),
   210	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 / rhs),
   211	            (Float(lhs), Integer(rhs)) => Float(lhs / *rhs as f64),
   212	            (Float(lhs), Float(rhs)) => Float(lhs / rhs),
   213	            (Null, Integer(_) | Float(_) | Null) => Null,
   214	            (Integer(_) | Float(_), Null) => Null,
   215	            (lhs, rhs) => return errinput!("can't divide {lhs} and {rhs}"),
   216	        })
   217	    }
   218	
   219	    /// Multiplies two values. Errors if invalid.
   220	    pub fn checked_mul(&self, other: &Self) -> Result<Self> {
   221	        use Value::*;
   222	
   223	        Ok(match (self, other) {
   224	            (Integer(lhs), Integer(rhs)) => match lhs.checked_mul(*rhs) {
   225	                Some(i) => Integer(i),
   226	                None => return errinput!("integer overflow"),
   227	            },
   228	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 * rhs),
   229	            (Float(lhs), Integer(rhs)) => Float(lhs * *rhs as f64),
   230	            (Float(lhs), Float(rhs)) => Float(lhs * rhs),
   231	            (Null, Integer(_) | Float(_) | Null) => Null,
   232	            (Integer(_) | Float(_), Null) => Null,
   233	            (lhs, rhs) => return errinput!("can't multiply {lhs} and {rhs}"),
   234	        })
   235	    }
   236	
   237	    /// Exponentiates two values. Errors if invalid.
   238	    pub fn checked_pow(&self, other: &Self) -> Result<Self> {
   239	        use Value::*;
   240	
   241	        Ok(match (self, other) {
   242	            (Integer(lhs), Integer(rhs)) if *rhs >= 0 => {
   243	                let rhs = (*rhs).try_into().or_else(|_| errinput!("integer overflow"))?;
   244	                match lhs.checked_pow(rhs) {
   245	                    Some(i) => Integer(i),
   246	                    None => return errinput!("integer overflow"),
   247	                }
   248	            }
   249	            (Integer(lhs), Integer(rhs)) => Float((*lhs as f64).powf(*rhs as f64)),
   250	            (Integer(lhs), Float(rhs)) => Float((*lhs as f64).powf(*rhs)),
   251	            (Float(lhs), Integer(rhs)) => Float((lhs).powi(*rhs as i32)),
   252	            (Float(lhs), Float(rhs)) => Float((lhs).powf(*rhs)),
   253	            (Integer(_) | Float(_), Null) => Null,
   254	            (Null, Integer(_) | Float(_) | Null) => Null,
   255	            (lhs, rhs) => return errinput!("can't exponentiate {lhs} and {rhs}"),
   256	        })
   257	    }
   258	
   259	    /// Finds the remainder of two values. Errors if invalid.
   260	    ///
   261	    /// NB: uses the remainder, not modulo, like Postgres. This means that for
   262	    /// negative values, the result has the sign of the dividend, rather than
   263	    /// always returning a positive value.
   264	    pub fn checked_rem(&self, other: &Self) -> Result<Self> {
   265	        use Value::*;
   266	
   267	        Ok(match (self, other) {
   268	            (Integer(_), Integer(0)) => return errinput!("can't divide by zero"),
   269	            (Integer(lhs), Integer(rhs)) => Integer(lhs % rhs),
   270	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 % rhs),
   271	            (Float(lhs), Integer(rhs)) => Float(lhs % *rhs as f64),
   272	            (Float(lhs), Float(rhs)) => Float(lhs % rhs),
   273	            (Integer(_) | Float(_) | Null, Null) => Null,
   274	            (Null, Integer(_) | Float(_)) => Null,
   275	            (lhs, rhs) => return errinput!("can't take remainder of {lhs} and {rhs}"),
   276	        })
   277	    }
   278	
   279	    /// Subtracts two values. Errors if invalid.
   280	    pub fn checked_sub(&self, other: &Self) -> Result<Self> {
   281	        use Value::*;
   282	
   283	        Ok(match (self, other) {
   284	            (Integer(lhs), Integer(rhs)) => match lhs.checked_sub(*rhs) {
   285	                Some(i) => Integer(i),
   286	                None => return errinput!("integer overflow"),
   287	            },
   288	            (Integer(lhs), Float(rhs)) => Float(*lhs as f64 - rhs),
   289	            (Float(lhs), Integer(rhs)) => Float(lhs - *rhs as f64),
   290	            (Float(lhs), Float(rhs)) => Float(lhs - rhs),
   291	            (Null, Integer(_) | Float(_) | Null) => Null,
   292	            (Integer(_) | Float(_), Null) => Null,
   293	            (lhs, rhs) => return errinput!("can't subtract {lhs} and {rhs}"),
   294	        })
   295	    }
   296	}
